-- Only synthetic records; all are rolled back, including messages and audit events.
begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();staff uuid:=gen_random_uuid();
 c uuid:=gen_random_uuid();other_c uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();tid uuid;legacy uuid:=gen_random_uuid();
 x jsonb;y jsonb;data jsonb;mid bigint;new_mid bigint;v bigint;denied boolean;u uuid;
begin
 foreach u in array array[a,b,other_user,staff] loop
  insert into auth.users(id,email,email_confirmed_at) values(u,u||'@example.invalid',now());
  insert into public.user_profiles(user_id,display_name) values(u,'Assist synthetic test');
 end loop;
 insert into public.clubs(id,name,slug,created_by) values(c,'Assist test','assist-'||c,a),(other_c,'Other Assist test','assist-'||other_c,other_user);
 insert into public.club_memberships(club_id,user_id,role,permission_role) values(c,a,'admin','admin'),(c,b,'player','none'),(other_c,other_user,'admin','admin');
 insert into public.platform_admins(user_id,role) values(staff,'support_admin');
 perform set_config('request.jwt.claim.sub',a::text,true);
 data:=jsonb_build_object('club_id',c,'request_id',rid,'subject','Grade labels','category','idea','body','Could we use shorter grade names?');
 x:=public.mirelion_assist('create',data);tid:=(x->>'thread_id')::uuid;mid:=(x->>'message_id')::bigint;
 assert public.mirelion_assist('create',data)=x,'Create retry returns original thread/message';
 assert (select count(*)=1 from mirelion_assist_private.messages where thread_id=tid),'Create retry never duplicates';
 denied:=false;begin perform public.mirelion_assist('create',data||'{"body":"Changed"}');exception when raise_exception then denied:=true;end;assert denied,'Cannot reuse request ID for changed body';
 assert (public.mirelion_assist('summary',jsonb_build_object('club_id',c))->>'unread')::int=0,'Own message is not unread';
 assert jsonb_array_length(public.mirelion_assist('list',jsonb_build_object('club_id',c))->'threads')=1,'Requester sees own thread';
 perform set_config('request.jwt.claim.sub',b::text,true);
 assert jsonb_array_length(public.mirelion_assist('list',jsonb_build_object('club_id',c))->'threads')=0,'Another club member cannot list private requests';
 denied:=false;begin perform public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',tid));exception when insufficient_privilege then denied:=true;end;assert denied,'Same-club privacy checked server-side';
 denied:=false;begin perform public.mirelion_assist('send',jsonb_build_object('platform',true,'thread_id',tid,'request_id',gen_random_uuid(),'body','Forged reply'));exception when insufficient_privilege then denied:=true;end;assert denied,'Cannot claim to be the platform';
 perform set_config('request.jwt.claim.sub',other_user::text,true);
 denied:=false;begin perform public.mirelion_assist('thread',jsonb_build_object('club_id',other_c,'thread_id',tid));exception when insufficient_privilege then denied:=true;end;assert denied,'Cross-club thread denied';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 assert (public.mirelion_assist('summary','{"platform":true}')->>'unread')::int>=1,'Platform sees incoming request';
 x:=public.mirelion_assist('send',jsonb_build_object('platform',true,'thread_id',tid,'request_id',gen_random_uuid(),'body','Yes, we can review that with you.'));
 new_mid:=(x->>'message_id')::bigint;
 x:=public.mirelion_assist('thread',jsonb_build_object('platform',true,'thread_id',tid));
 assert x->'messages'->1->>'side'='team','Reply side comes from server authorization';
 v:=(x->'thread'->>'version')::bigint;
 perform set_config('request.jwt.claim.sub',a::text,true);
 assert (public.mirelion_assist('summary',jsonb_build_object('club_id',c))->>'unread')::int=1,'Club sees unread team reply';
 perform public.mirelion_assist('read',jsonb_build_object('club_id',c,'thread_id',tid,'through',mid));
 assert (public.mirelion_assist('summary',jsonb_build_object('club_id',c))->>'unread')::int=1,'Reading old snapshot cannot consume a newer reply';
 perform public.mirelion_assist('read',jsonb_build_object('club_id',c,'thread_id',tid,'through',new_mid));
 assert (public.mirelion_assist('summary',jsonb_build_object('club_id',c))->>'unread')::int=0,'Reading shown reply clears badge';
 perform public.mirelion_assist('read',jsonb_build_object('club_id',c,'thread_id',tid,'through',mid));
 assert (public.mirelion_assist('summary',jsonb_build_object('club_id',c))->>'unread')::int=0,'Read cursor never moves backwards';
 denied:=false;begin perform public.mirelion_assist('read',jsonb_build_object('club_id',c,'thread_id',tid,'through',999999999));exception when raise_exception then denied:=true;end;assert denied,'Forged future read cursor rejected';
 x:=public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',tid,'before',new_mid));
 assert jsonb_array_length(x->'messages')=1,'Earlier-message pagination uses exact thread cursor';
 denied:=false;begin perform public.mirelion_assist('status',jsonb_build_object('club_id',c,'thread_id',tid,'request_id',gen_random_uuid(),'version',v-1,'status','resolved'));exception when raise_exception then denied:=true;end;assert denied,'Stale resolve cannot hide new messages';
 x:=public.mirelion_assist('status',jsonb_build_object('club_id',c,'thread_id',tid,'request_id',gen_random_uuid(),'version',v,'status','resolved'));
 assert jsonb_array_length(public.mirelion_assist('list',jsonb_build_object('club_id',c,'status','resolved'))->'threads')=1,'Resolved history remains readable';
 x:=public.mirelion_assist('send',jsonb_build_object('club_id',c,'thread_id',tid,'request_id',gen_random_uuid(),'body','One more detail'));
 assert (public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',tid))->'thread'->>'status')='open','Follow-up reopens resolved conversation';
 denied:=false;begin perform public.mirelion_assist('send',jsonb_build_object('club_id',c,'thread_id',tid,'request_id',gen_random_uuid(),'body',repeat('x',6001)));exception when raise_exception then denied:=true;end;assert denied,'Oversized message rejected';
 denied:=false;begin perform public.mirelion_assist('create',data||jsonb_build_object('request_id',gen_random_uuid(),'body',' '));exception when raise_exception then denied:=true;end;assert denied,'Whitespace-only message rejected';
 perform set_config('request.jwt.claim.sub',b::text,true);
 data:=data||jsonb_build_object('request_id',gen_random_uuid());
 perform public.mirelion_assist('create',data);
 delete from public.club_memberships where club_id=c and user_id=b;
 denied:=false;begin perform public.mirelion_assist('create',data);exception when insufficient_privilege then denied:=true;end;assert denied,'Revoked membership also blocks retry receipts';
 insert into public.club_memberships(club_id,user_id,role,permission_role) values(c,b,'player','none');
 perform set_config('request.jwt.claim.sub',a::text,true);
 insert into public.club_batting_guide_threads(id,club_id,user_id,status,human_handoff_reason) values(legacy,c,a,'open','');
 insert into public.club_batting_guide_messages(thread_id,role,content) values(legacy,'user','Earlier Guide question');
 update public.club_batting_guide_threads set status='handoff_requested',human_handoff_reason='Please help with this' where id=legacy;
 select id into tid from mirelion_assist_private.threads where legacy_thread_id=legacy;
 assert tid is not null,'Old browser handoff is delivered to Assist';
 assert (public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',tid))->'thread'->'guide_context'->0->>'content')='Earlier Guide question','Legacy Guide context preserved';
 update public.club_batting_guide_threads set updated_at=now() where id=legacy;
 assert (select count(*)=1 from mirelion_assist_private.messages where thread_id=tid),'Routine Guide refresh does not duplicate request';
 x:=public.mirelion_assist('create',data||jsonb_build_object('request_id',gen_random_uuid(),'include_guide',true));
 y:=public.mirelion_assist('thread',jsonb_build_object('club_id',c,'thread_id',x->>'thread_id'));
 assert jsonb_array_length(y->'thread'->'guide_context')=1,'Guide context is shared only by the requester';
 perform set_config('request.jwt.claim.sub','',true);
 denied:=false;begin perform public.mirelion_assist('summary','{"platform":true}');exception when insufficient_privilege then denied:=true;end;assert denied,'Signed-out access denied';
 assert not has_function_privilege('anon','public.mirelion_assist(text,jsonb)','execute'),'Anonymous RPC privilege denied';
 assert not has_table_privilege('authenticated','mirelion_assist_private.messages','select'),'Message tables cannot be read directly';
 assert not has_table_privilege('authenticated','mirelion_assist_private.threads','update'),'Direct thread changes denied';
 assert not has_function_privilege('authenticated','mirelion_assist_private.import_handoff()','execute'),'Migration trigger helper is private';
 assert not (select prosecdef from pg_proc where oid='public.mirelion_assist(text,jsonb)'::regprocedure),'Public wrapper uses invoker security';
 assert (select bool_and(relrowsecurity) from pg_class where relnamespace='mirelion_assist_private'::regnamespace and relkind='r'),'All private tables retain RLS';
end $test$;
rollback;
